'use strict';
let historicalEvidenceState=null;
function showHistoricalEvidence(row,payload,result){
 const state={context:historyContext(),payload,row,result,participantId:result.item.bundle.race.participants[0]?.id,tab:'Summary',offset:0,tablePage:0,note:'',error:'',serial:0};historicalEvidenceState=state;
 modal('Historical import · '+result.item.bundle.race.name,`<div id="historical-evidence" class="shared-history">${historicalEvidenceHtml(state)}</div>`,result.status==='pending'?async()=>{if(state.decision)throw Error('Retry the pending approval or reopen this evidence to check its decision.');const note=$('#history-reject-note')?.value??state.note;await api('historyImport',{...payload,action:'reject',note});if(db._view)db._view.request=null;}:null,'Reject import');
 syncHistoricalEvidenceControls(state);
}
function historicalEvidenceHtml(s){
 const result=s.result,b=result.item.bundle,race=b.race,p=race.participants.find(p=>p.id===s.participantId),tabs=['Summary','Laps','Configuration','Classification'];
 const notice=result.status==='approved'?'This evidence was approved into shared history. Its approval receipt remains attached; later corrections or withdrawals determine its current contribution.':result.status!=='pending'?'This evidence was not accepted. '+result.message:result.approvalEnabled?'Evidence only until approved in Paddock. Approval preserves unknowns and grants no record eligibility.':'Evidence only. Historical acceptance is disabled; these laps are not part of accepted performance history.';
 let content='';
 if(s.tab==='Summary')content=`<p class="prewrap">${esc(b.provenance.evidence)}</p><p><strong>Missing evidence declared by source:</strong> ${esc(b.provenance.missing.join(', ')||'None declared by sender')}</p><p class="tiny muted">Unknown values stay unknown. No current car configuration, timing or track length will be substituted.</p><div class="history-evidence-grid">${race.participants.map(p=>{const missing=p.evidenceSummary?.missing||{};return `<section class="panel"><h3>${esc(p.displayName)}</h3>${badge(p.kind==='virtual'?'Virtual':p.carId?'Linked car':'Unlinked',p.carId&&p.linkedCar?'info':'')}<p>${esc(p.carId?p.linkedCar?'Library car: '+p.linkedCar.name+(p.linkedCar.archived?' (archived)':''):'Missing library car · '+p.carId:'No physical car will receive these results')}</p><p>${p.lapCount} supplied laps · ${p.evidenceSummary?.validLaps??0} timed, valid, non-pit</p><p>${historyNumber(p.evidenceSummary?.distanceM)} m known travel${missing.distance?' · '+missing.distance+' unknown distances':''}</p><p class="tiny muted">${esc(Object.entries(missing).filter(([,n])=>n).map(([k,n])=>n+' unknown '+k).join(' · ')||'No unknown lap fields detected')}</p><p>${p.configuration?'Configuration evidence supplied':'Configuration unknown'}</p></section>`;}).join('')}</div><p class="note">Only linked physical cars can receive contributions. Historical intake grants no personal or track-record eligibility. The full evidence remains available for inspection.</p>${result.accepted?`<p class="note warning">${result.status==='approved'?'Approval receipt':'Conflicting accepted result'} · revision ${result.accepted.revision} (${esc(result.accepted.state)}). Do not add the same session again.</p>`:''}<p class="prewrap">${esc(b.context.notes)}</p>`;
 if(s.tab==='Configuration')content=p?historyConfiguration(p):'<p>No participant.</p>';
 if(s.tab==='Laps')content=p?`<p class="muted">${p.lapCount} supplied laps · showing ${p.laps.length? p.lapPage.offset+1:0}–${p.lapPage.offset+p.laps.length}. Original order; no inferred values.</p>${historyTable(['Lap','Heat','Driver','Lane','Time','Completion offset','Valid','Pit','Personal record','Track record','Distance','Flags / reason'],p.laps.map(l=>HistoryViewModel.lap(l,p,race,true)))}<div class="actions mt">${s.offset?btn('Previous evidence laps','history-evidence-prev'):''}${p.lapPage.nextOffset!==null?btn('Next evidence laps','history-evidence-next'):''}</div>`:'<p>No participant.</p>';
 if(s.tab==='Classification'){const table=HistoryViewModel.classification(race,b.context);content='<p class="note">Proposed awarded results. These do not change physical travel or accepted history while awaiting review. Points and scoring values are shown separately; unknown evidence stays unknown.</p>'+historyRowsPage(table.headers,table.rows,s).replaceAll('history-view-rows-','history-evidence-rows-');}
 return `<p class="note info">${esc(notice)}</p>${s.error?`<p class="note warning" role="alert">${esc(s.error)}</p>`:''}<p>${esc(race.track.name||'Unknown track')} · ${esc(historyDate(race.startedAt))} · ${esc(race.type)}</p><label class="history-participant">Participant<select id="history-evidence-participant">${race.participants.map(p=>`<option value="${esc(p.id)}" ${p.id===s.participantId?'selected':''}>${esc(p.displayName)}</option>`).join('')}</select></label><div class="tabs history-tabs" role="tablist" aria-label="Historical evidence">${tabs.map(t=>`<button type="button" role="tab" aria-selected="${s.tab===t}" class="${s.tab===t?'active':''}" data-action="history-evidence-tab" data-id="${t}">${t}</button>`).join('')}</div><div class="history-tab-content">${content}</div><p class="tiny muted">Original source: ${esc(s.row.sourceId)} · Session: ${esc(s.row.sessionId)} · Sender: ${esc(s.row.batch.editor.name||s.row.batch.editor.application)}</p>${result.status==='pending'?`${result.approvalEnabled?`<button class="btn primary" type="button" data-action="history-evidence-approve" ${s.busy||result.recoveryChanged?'disabled':''}>${s.busy?'Approving…':s.decision?'Retry approval':'Approve into shared history'}</button>${result.recoveryChanged?'<p class="note warning">This evidence predates a database restore. Reconcile it with Timing before submitting again.</p>':''}`:'<button class="btn" type="button" disabled title="Historical acceptance is not enabled yet">Approve (not yet available)</button>'}<div class="field"><label for="history-reject-note">${result.approvalEnabled?'Review note':'Reason for rejection'}</label><textarea rows="3" id="history-reject-note" maxlength="2000" ${s.decision?'disabled':''} placeholder="Record the reason for your decision">${esc(s.note)}</textarea></div>`:'<p>'+esc(result.message)+'</p>'}`;
}
function syncHistoricalEvidenceControls(s){
 const footer=$('#dialog .dialog-footer'),approve=$('#historical-evidence [data-action="history-evidence-approve"]');if(!footer)return;
 footer.querySelector('[data-action="history-evidence-approve"]')?.remove();if(approve)footer.append(approve);
 const reject=footer.querySelector('button[type="submit"]');if(reject){reject.classList.toggle('primary',!s.result.approvalEnabled);reject.disabled=!!s.decision||!!s.busy;}
 if(s.result.status!=='pending'){modalSubmit=null;reject?.remove();const close=footer.querySelector('[data-action="close-modal"]');if(close)close.textContent='Close';}
}
function paintHistoricalEvidence(){const s=historicalEvidenceState,root=$('#historical-evidence');if(s&&root&&historyContext()===s.context){root.innerHTML=historicalEvidenceHtml(s);syncHistoricalEvidenceControls(s);}}
async function loadHistoricalEvidence(){
 const s=historicalEvidenceState,serial=++s.serial;s.error='';
 try{const result=await api('historyImport',{...s.payload,action:'inspect',participantId:s.participantId,offset:s.offset});if(historicalEvidenceState!==s||s.serial!==serial||historyContext()!==s.context||!$('#historical-evidence'))return;s.result=result;}
 catch(e){if(historicalEvidenceState!==s||s.serial!==serial)return;s.error=e.message;}
 paintHistoricalEvidence();
}
async function historicalEvidenceAction(action,id){
 if(!action.startsWith('history-evidence-'))return false;const s=historicalEvidenceState;if(!s)return true;s.note=$('#history-reject-note')?.value??s.note;
 if(action==='history-evidence-approve'){
  if(s.busy||s.result.status!=='pending'||!s.result.approvalEnabled||s.result.recoveryChanged||historyContext()!==s.context)return true;
  // Retain the exact decision across uncertain acknowledgements. The backend
  // derives a durable operation ID from the immutable evidence identity.
  s.decision??={...s.payload,action:'approve',note:s.note};s.busy=true;s.error='';paintHistoricalEvidence();
  const reject=$('#dialog .dialog-footer button[type="submit"]');if(reject)reject.disabled=true;
  try{await api('historyImport',s.decision);if(historicalEvidenceState===s&&historyContext()===s.context&&$('#historical-evidence')){if(db._view)db._view.request=null;$('#dialog').close();modalSubmit=null;render();}}
  catch(e){s.error=e.message;}
  finally{s.busy=false;paintHistoricalEvidence();}return true;
 }
 if(action==='history-evidence-tab'){s.tab=id;s.tablePage=0;if(id==='Laps'){s.offset=0;await loadHistoricalEvidence();}else paintHistoricalEvidence();}
 if(action==='history-evidence-prev'||action==='history-evidence-next'){const p=s.result.item.bundle.race.participants.find(p=>p.id===s.participantId);s.offset=action.endsWith('prev')?Math.max(0,s.offset-100):p.lapPage.nextOffset??s.offset;await loadHistoricalEvidence();}
 if(action==='history-evidence-rows-prev'||action==='history-evidence-rows-next'){s.tablePage=Math.max(0,s.tablePage+(action.endsWith('prev')?-1:1));paintHistoricalEvidence();}return true;
}
document.addEventListener('change',async e=>{if(e.target.id!=='history-evidence-participant')return;const s=historicalEvidenceState;if(!s)return;s.note=$('#history-reject-note')?.value??s.note;s.participantId=e.target.value;s.offset=0;s.tablePage=0;if(s.tab==='Laps')await loadHistoricalEvidence();else paintHistoricalEvidence();});
document.getElementById('dialog').addEventListener('close',()=>queueMicrotask(()=>{if(!$('#dialog').open||!$('#historical-evidence'))historicalEvidenceState=null;}));
